package com.example.demo.staffing;

import com.example.demo.accounting.AccountingService;
import com.example.demo.audit.AuditService;
import com.example.demo.common.exception.BadRequestException;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;
import static com.example.demo.accounting.PayrollBreakdown.money;

@Service @RequiredArgsConstructor @Transactional
public class StaffingService {
    private final AccountingService accounting;
    private final JdbcTemplate jdbc;
    private final ObjectMapper json;
    private final AuditService audit;

    public record Worker(long employeeId,String classification,String employmentTerm,String payBasis,String vendorName,String notes,int version) {}
    public record Authorization(long employeeId,String category,String sponsor,String reference,LocalDate validFrom,LocalDate validUntil,Long documentId,String notes,int version) {}
    public record Client(String name,String email,String address,boolean active,int version) {}
    public record Assignment(long employeeId,long clientId,String title,String contractReference,String workLocation,String workState,String workCountry,LocalDate startsOn,LocalDate endsOn,Long payrollContractId,BigDecimal payRate,BigDecimal billRate,BigDecimal overtimePayRate,BigDecimal overtimeBillRate,String status,int version) {}
    public record TimeEntry(long assignmentId,LocalDate workDate,BigDecimal regularHours,BigDecimal overtimeHours,String description,Long sourceTimesheetId,int version) {}
    public record Transition(String status,String reason,int version) {}
    public record Invoice(long clientId,List<Long> timeEntryIds,LocalDate invoiceDate,LocalDate dueDate,BigDecimal taxPercent,String requestKey) {}
    public record Receipt(LocalDate date,BigDecimal amount,String account,String reference,String requestKey) {}
    public record VoidInvoice(LocalDate date,String reason,String requestKey) {}

    private AccountingService.Context scope(long companyId) { return accounting.context(companyId,false); }
    private String actor(){return SecurityContextHolder.getContext().getAuthentication().getName();}
    private static void text(String s,int max,String label){if(s==null || s.isBlank() || s.length()>max)throw new BadRequestException(label+" is required (up to "+max+" characters)");}
    private static void optional(String s,int max,String label){if(s!=null && s.length()>max)throw new BadRequestException(label+" is too long");}
    private static void choice(String s,Set<String> options,String label){if(s==null || !options.contains(s))throw new BadRequestException("Choose a valid "+label);}
    private static void amount(BigDecimal value,int scale,String label){if(value==null || value.signum()<0 || value.scale()>scale || value.precision()>14 || (scale==4 && value.precision()-value.scale()>10))throw new BadRequestException("Enter a non-negative "+label+" with at most "+scale+" decimals");}
    private static void actual(LocalDate d){if(d==null || d.isAfter(LocalDate.now()) || d.getYear()<2000)throw new BadRequestException("Enter an actual date from 2000 through today");}
    private static void period(LocalDate start,LocalDate end){if(start==null || start.getYear()<1900 || (end!=null && end.isBefore(start)))throw new BadRequestException("Enter a valid date range");}
    private void lock(long company){jdbc.queryForList("SELECT id FROM public.companies WHERE id=? FOR UPDATE",company);}
    private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private String hash(Object value){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(encode(value).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
    private static YearMonth month(String value){try{return YearMonth.parse(value);}catch(Exception e){throw new BadRequestException("Choose a month (YYYY-MM)");}}
    private Map<String,Object> one(String table,long company,long id){var rows=jdbc.queryForList("SELECT * FROM public."+table+" WHERE company_id=? AND id=?",company,id);if(rows.isEmpty())throw new AccessDeniedException("Record is outside selected company");return rows.getFirst();}
    private void employee(AccountingService.Context c,long id){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM "+c.schema()+".employees WHERE id=? AND company_id=? AND is_active=true)",Boolean.class,id,c.companyId())))throw new AccessDeniedException("Select an active worker in this company");}
    private void updated(int count){if(count!=1)throw new BadRequestException("Record changed in another session. Refresh and try again");}
    private void audit(String kind,Object id,Object before,Object after){audit.log("Staffing "+kind,id,before==null?"CREATED":"UPDATED",before,after);}

    public Map<String,Object> overview(long company,String month){
        var c=scope(company);var ym=month(month);
        var employees=jdbc.queryForList("SELECT e.id,trim(concat(e.employee_first_name,' ',e.employee_last_name)) name,e.badge_id,w.classification,w.employment_term,w.pay_basis,w.vendor_name,w.notes,w.version FROM "+c.schema()+".employees e LEFT JOIN public.staffing_worker_profiles w ON w.company_id=e.company_id AND w.employee_id=e.id WHERE e.company_id=? AND e.is_active=true ORDER BY name LIMIT 5001",company);
        if(employees.size()>5000)throw new BadRequestException("Select a smaller company; staffing supports up to 5,000 active workers per view");
        var clients=jdbc.queryForList("SELECT * FROM public.staffing_clients WHERE company_id=? ORDER BY name",company);
        var assignments=jdbc.queryForList("SELECT a.*,c.name client,trim(concat(e.employee_first_name,' ',e.employee_last_name)) employee FROM public.staffing_assignments a JOIN public.staffing_clients c ON c.id=a.client_id JOIN "+c.schema()+".employees e ON e.id=a.employee_id WHERE a.company_id=? ORDER BY a.starts_on DESC,a.id DESC LIMIT 5000",company);
        var authorizations=jdbc.queryForList("SELECT a.*,trim(concat(e.employee_first_name,' ',e.employee_last_name)) employee,d.title document_title FROM public.staffing_authorizations a JOIN "+c.schema()+".employees e ON e.id=a.employee_id LEFT JOIN "+c.schema()+".employee_documents d ON d.id=a.document_id AND d.employee_id=a.employee_id AND d.company_id=a.company_id WHERE a.company_id=? ORDER BY a.valid_until NULLS LAST,a.id DESC LIMIT 5000",company);
        var documents=jdbc.queryForList("SELECT id,employee_id,title FROM "+c.schema()+".employee_documents WHERE company_id=? AND is_active=true ORDER BY title LIMIT 5000",company);
        var contracts=jdbc.queryForList("SELECT id,employee_id,contract_name,contract_status FROM "+c.schema()+".contracts WHERE company_id=? AND is_active=true ORDER BY id DESC LIMIT 5000",company);
        var projectTime=jdbc.queryForList("SELECT t.id,t.employee_id,t.date,t.hours,t.description FROM "+c.schema()+".timesheets t WHERE t.company_id=? AND t.is_active=true AND t.date BETWEEN ? AND ? AND NOT EXISTS(SELECT 1 FROM public.staffing_time_entries s WHERE s.company_id=t.company_id AND s.source_timesheet_id=t.id) ORDER BY t.date DESC LIMIT 5000",company,ym.atDay(1),ym.atEndOfMonth());
        String currency=jdbc.queryForObject("SELECT coalesce(nullif(currency,''),'UNSPECIFIED') FROM public.companies WHERE id=?",String.class,company);
        var result=new LinkedHashMap<String,Object>();result.put("workers",employees);result.put("clients",clients);result.put("assignments",assignments);result.put("authorizations",authorizations);result.put("documents",documents);result.put("contracts",contracts);result.put("project_time",projectTime);result.put("time_entries",times(company,ym));result.put("invoices",invoices(company));result.put("currency",currency);result.put("country_profile",c.profile());return result;
    }

    public void worker(long company,Worker r){
        var c=scope(company);lock(company);employee(c,r.employeeId());
        choice(r.classification(),Set.of("EMPLOYEE","INDEPENDENT_CONTRACTOR","VENDOR_WORKER"),"worker classification");choice(r.employmentTerm(),Set.of("PERMANENT","FIXED_TERM"),"employment term");choice(r.payBasis(),Set.of("HOURLY","SALARIED"),"pay basis");optional(r.vendorName(),160,"Vendor name");optional(r.notes(),1000,"Notes");if(r.classification().equals("VENDOR_WORKER"))text(r.vendorName(),160,"Vendor name");
        var previous=jdbc.queryForList("SELECT * FROM public.staffing_worker_profiles WHERE company_id=? AND employee_id=?",company,r.employeeId());
        if(previous.isEmpty()){if(r.version()!=0)throw new BadRequestException("Refresh worker profile");jdbc.update("INSERT INTO public.staffing_worker_profiles(company_id,employee_id,classification,employment_term,pay_basis,vendor_name,notes,updated_by) VALUES(?,?,?,?,?,?,?,?)",company,r.employeeId(),r.classification(),r.employmentTerm(),r.payBasis(),r.vendorName(),r.notes(),actor());}
        else updated(jdbc.update("UPDATE public.staffing_worker_profiles SET classification=?,employment_term=?,pay_basis=?,vendor_name=?,notes=?,version=version+1,updated_by=?,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND employee_id=? AND version=?",r.classification(),r.employmentTerm(),r.payBasis(),r.vendorName(),r.notes(),actor(),company,r.employeeId(),r.version()));
        audit("worker",r.employeeId(),previous.isEmpty()?null:previous.getFirst(),r);
    }
    public long authorization(long company,Long id,Authorization r){
        var c=scope(company);lock(company);employee(c,r.employeeId());choice(r.category(),Set.of("CITIZEN","PERMANENT_RESIDENT","H1B","H1B1","L1","F1_OPT","F1_STEM_OPT","EAD","TN","E3","UK_SKILLED_WORKER","UK_GRADUATE","UK_DEPENDANT","UK_GLOBAL_TALENT","UK_SETTLED","UK_PRE_SETTLED","OTHER"),"work authorization category");period(r.validFrom(),r.validUntil());optional(r.sponsor(),200,"Sponsor");optional(r.reference(),160,"Reference");optional(r.notes(),1000,"Notes");if(Set.of("H1B","H1B1","L1","E3","UK_SKILLED_WORKER").contains(r.category()))text(r.sponsor(),200,"Sponsoring employer");if(!Set.of("CITIZEN","PERMANENT_RESIDENT","UK_SETTLED").contains(r.category()) && r.validUntil()==null)throw new BadRequestException("Expiry date is required for temporary work authorization");
        if(r.documentId()!=null && !Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM "+c.schema()+".employee_documents WHERE id=? AND employee_id=? AND company_id=? AND is_active=true)",Boolean.class,r.documentId(),r.employeeId(),company)))throw new AccessDeniedException("Document is outside this worker's company");
        Map<String,Object> before=id==null?null:one("staffing_authorizations",company,id);
        if(id==null)id=jdbc.queryForObject("INSERT INTO public.staffing_authorizations(company_id,employee_id,category,sponsor,reference,valid_from,valid_until,document_id,notes,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,company,r.employeeId(),r.category(),r.sponsor(),r.reference(),r.validFrom(),r.validUntil(),r.documentId(),r.notes(),actor(),actor());
        else {if(((Number)before.get("employee_id")).longValue()!=r.employeeId())throw new BadRequestException("Work authorization worker cannot be changed");updated(jdbc.update("UPDATE public.staffing_authorizations SET category=?,sponsor=?,reference=?,valid_from=?,valid_until=?,document_id=?,notes=?,updated_by=?,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND company_id=? AND version=?",r.category(),r.sponsor(),r.reference(),r.validFrom(),r.validUntil(),r.documentId(),r.notes(),actor(),id,company,r.version()));}
        audit("authorization",id,before,r);return id;
    }
    public long client(long company,Long id,Client r){
        scope(company);lock(company);text(r.name(),160,"Client name");optional(r.email(),200,"Email");optional(r.address(),1000,"Billing address");if(r.email()!=null && !r.email().isBlank() && !r.email().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new BadRequestException("Enter a valid client email");var before=id==null?null:one("staffing_clients",company,id);
        if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_clients WHERE company_id=? AND name=? AND id<>?)",Boolean.class,company,r.name().trim(),id==null?0:id)))throw new BadRequestException("Client name already exists");
        if(id==null)id=jdbc.queryForObject("INSERT INTO public.staffing_clients(company_id,name,email,address,active,created_by) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,company,r.name().trim(),r.email(),r.address(),r.active(),actor());
        else updated(jdbc.update("UPDATE public.staffing_clients SET name=?,email=?,address=?,active=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND id=? AND version=?",r.name().trim(),r.email(),r.address(),r.active(),company,id,r.version()));
        audit("client",id,before,r);return id;
    }
    public long assignment(long company,Long id,Assignment r){
        var c=scope(company);lock(company);employee(c,r.employeeId());var client=one("staffing_clients",company,r.clientId());if(id==null && !Boolean.TRUE.equals(client.get("active")))throw new BadRequestException("Select an active client");text(r.title(),200,"Project / assignment");text(r.workLocation(),300,"Work location");text(r.workCountry(),100,"Work country");optional(r.workState(),100,"Work state");optional(r.contractReference(),160,"Contract reference");period(r.startsOn(),r.endsOn());choice(r.status(),Set.of("ACTIVE","ENDED"),"assignment status");for(var rate:Arrays.asList(r.payRate(),r.billRate(),r.overtimePayRate(),r.overtimeBillRate()))amount(rate,4,"rate");
        if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_worker_profiles WHERE company_id=? AND employee_id=?)",Boolean.class,company,r.employeeId())))throw new BadRequestException("Configure worker classification before creating an assignment");
        if(r.payrollContractId()!=null && !Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM "+c.schema()+".contracts WHERE id=? AND employee_id=? AND company_id=? AND is_active=true)",Boolean.class,r.payrollContractId(),r.employeeId(),company)))throw new AccessDeniedException("Payroll contract is outside this worker's company");
        String currency=jdbc.queryForObject("SELECT currency FROM public.companies WHERE id=?",String.class,company);if(currency==null || !currency.matches("[A-Z]{3}"))throw new BadRequestException("Configure company currency before assigning rates");var before=id==null?null:one("staffing_assignments",company,id);
        if(id==null)id=jdbc.queryForObject("INSERT INTO public.staffing_assignments(company_id,employee_id,client_id,title,contract_reference,work_location,work_state,work_country,starts_on,ends_on,payroll_contract_id,pay_rate,bill_rate,overtime_pay_rate,overtime_bill_rate,currency,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,company,r.employeeId(),r.clientId(),r.title(),r.contractReference(),r.workLocation(),r.workState(),r.workCountry(),r.startsOn(),r.endsOn(),r.payrollContractId(),r.payRate(),r.billRate(),r.overtimePayRate(),r.overtimeBillRate(),currency,r.status(),actor());
        else {if(((Number)before.get("employee_id")).longValue()!=r.employeeId() || ((Number)before.get("client_id")).longValue()!=r.clientId())throw new BadRequestException("Create a new assignment to change worker or client");updated(jdbc.update("UPDATE public.staffing_assignments SET title=?,contract_reference=?,work_location=?,work_state=?,work_country=?,starts_on=?,ends_on=?,payroll_contract_id=?,pay_rate=?,bill_rate=?,overtime_pay_rate=?,overtime_bill_rate=?,status=?,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND id=? AND version=?",r.title(),r.contractReference(),r.workLocation(),r.workState(),r.workCountry(),r.startsOn(),r.endsOn(),r.payrollContractId(),r.payRate(),r.billRate(),r.overtimePayRate(),r.overtimeBillRate(),r.status(),company,id,r.version()));}
        audit("assignment",id,before,r);return id;
    }
    private static LocalDate day(Object value){return ((java.sql.Date)value).toLocalDate();}
    private String sourceHash(AccountingService.Context c,long id,long worker,LocalDate date,BigDecimal hours){var rows=jdbc.queryForList("SELECT employee_id,date,hours FROM "+c.schema()+".timesheets WHERE id=? AND company_id=? AND is_active=true",id,c.companyId());if(rows.isEmpty())throw new BadRequestException("Project time entry is unavailable");var row=rows.getFirst();if(((Number)row.get("employee_id")).longValue()!=worker || !date.equals(day(row.get("date"))) || money(row.get("hours")).compareTo(hours)!=0)throw new BadRequestException("Project time entry worker, date and hours must match");return hash(List.of(worker,date.toString(),money(hours).toPlainString()));}
    private void checkSource(AccountingService.Context c,Map<String,Object> row){if(row.get("source_timesheet_id")!=null){String current=sourceHash(c,((Number)row.get("source_timesheet_id")).longValue(),((Number)row.get("employee_id")).longValue(),day(row.get("work_date")),money(row.get("regular_hours")).add(money(row.get("overtime_hours"))));if(!current.equals(row.get("source_hash")))throw new BadRequestException("Project timesheet changed; review staffing hours before approval or billing");}}
    public long time(long company,Long id,TimeEntry r){
        var c=scope(company);lock(company);var a=one("staffing_assignments",company,r.assignmentId());long worker=((Number)a.get("employee_id")).longValue();employee(c,worker);actual(r.workDate());amount(r.regularHours(),2,"regular hours");amount(r.overtimeHours(),2,"overtime hours");BigDecimal hours=r.regularHours().add(r.overtimeHours());if(hours.signum()==0 || hours.compareTo(new BigDecimal("24"))>0)throw new BadRequestException("Daily hours must be greater than zero and no more than 24");optional(r.description(),1000,"Description");
        if(!"ACTIVE".equals(a.get("status")) || r.workDate().isBefore(day(a.get("starts_on"))) || (a.get("ends_on")!=null && r.workDate().isAfter(day(a.get("ends_on")))))throw new BadRequestException("Work date is outside an active assignment");
        var before=id==null?null:one("staffing_time_entries",company,id);if(before!=null && (!Set.of("DRAFT","REJECTED").contains(before.get("status")) || linked(id)))throw new BadRequestException("Only draft/rejected, uninvoiced time can be edited");if(before!=null && ((Number)before.get("assignment_id")).longValue()!=r.assignmentId())throw new BadRequestException("Assignment cannot be changed on a time entry");
        if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_time_entries WHERE assignment_id=? AND work_date=? AND id<>?)",Boolean.class,r.assignmentId(),r.workDate(),id==null?0:id)))throw new BadRequestException("An entry already exists for this assignment and day");
        BigDecimal existing=jdbc.queryForObject("SELECT coalesce(sum(regular_hours+overtime_hours),0) FROM public.staffing_time_entries WHERE company_id=? AND employee_id=? AND work_date=? AND id<>?",BigDecimal.class,company,worker,r.workDate(),id==null?0:id);if(existing.add(hours).compareTo(new BigDecimal("24"))>0)throw new BadRequestException("Worker's total hours exceed 24 for this day");
        String source=null;if(r.sourceTimesheetId()!=null){if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_time_entries WHERE company_id=? AND source_timesheet_id=? AND id<>?)",Boolean.class,company,r.sourceTimesheetId(),id==null?0:id)))throw new BadRequestException("Project time entry is already imported");source=sourceHash(c,r.sourceTimesheetId(),worker,r.workDate(),hours);}
        if(r.overtimeHours().signum()>0 && (money(a.get("overtime_pay_rate")).signum()==0 || money(a.get("overtime_bill_rate")).signum()==0))throw new BadRequestException("Configure explicit overtime pay and bill rates before recording overtime");
        if(id==null)id=jdbc.queryForObject("INSERT INTO public.staffing_time_entries(company_id,assignment_id,employee_id,work_date,regular_hours,overtime_hours,description,source_timesheet_id,source_hash,pay_rate,bill_rate,overtime_pay_rate,overtime_bill_rate,currency,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,company,r.assignmentId(),worker,r.workDate(),r.regularHours(),r.overtimeHours(),r.description(),r.sourceTimesheetId(),source,a.get("pay_rate"),a.get("bill_rate"),a.get("overtime_pay_rate"),a.get("overtime_bill_rate"),a.get("currency"),actor());
        else updated(jdbc.update("UPDATE public.staffing_time_entries SET work_date=?,regular_hours=?,overtime_hours=?,description=?,source_timesheet_id=?,source_hash=?,pay_rate=?,bill_rate=?,overtime_pay_rate=?,overtime_bill_rate=?,currency=?,status='DRAFT',review_reason=NULL,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE company_id=? AND id=? AND version=?",r.workDate(),r.regularHours(),r.overtimeHours(),r.description(),r.sourceTimesheetId(),source,a.get("pay_rate"),a.get("bill_rate"),a.get("overtime_pay_rate"),a.get("overtime_bill_rate"),a.get("currency"),company,id,r.version()));
        audit("time",id,before,r);return id;
    }
    private boolean linked(long id){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_invoice_lines WHERE time_entry_id=? AND released=false)",Boolean.class,id));}
    public void transition(long company,long id,Transition r){var c=scope(company);lock(company);var before=one("staffing_time_entries",company,id);if(linked(id))throw new BadRequestException("Void the linked invoice before changing approved time");String from=(String)before.get("status");boolean allowed=switch(r.status()==null?"":r.status()){case "SUBMITTED"->Set.of("DRAFT","REJECTED").contains(from);case "APPROVED"->from.equals("SUBMITTED");case "REJECTED"->Set.of("SUBMITTED","APPROVED").contains(from);default->false;};if(!allowed)throw new BadRequestException("Invalid time approval transition");if(r.status().equals("REJECTED"))text(r.reason(),500,"Review reason");else optional(r.reason(),500,"Review reason");if(!r.status().equals("REJECTED"))checkSource(c,before);updated(jdbc.update("UPDATE public.staffing_time_entries SET status=?,review_reason=?,submitted_by=CASE WHEN ?='SUBMITTED' THEN ? ELSE submitted_by END,approved_by=CASE WHEN ?='APPROVED' THEN ? ELSE NULL END,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND company_id=? AND version=?",r.status(),r.reason(),r.status(),actor(),r.status(),actor(),id,company,r.version()));audit("time approval",id,before,r);}

    private List<Map<String,Object>> times(long company,YearMonth ym){return jdbc.queryForList("SELECT t.*,a.title,a.client_id,a.payroll_contract_id,c.name client,trim(concat(e.employee_first_name,' ',e.employee_last_name)) employee,w.classification,w.pay_basis,(SELECT il.invoice_id FROM public.staffing_invoice_lines il WHERE il.time_entry_id=t.id AND il.released=false) invoice_id FROM public.staffing_time_entries t JOIN public.staffing_assignments a ON a.id=t.assignment_id JOIN public.staffing_clients c ON c.id=a.client_id JOIN public.companies co ON co.id=t.company_id JOIN "+scope(company).schema()+".employees e ON e.id=t.employee_id LEFT JOIN public.staffing_worker_profiles w ON w.company_id=t.company_id AND w.employee_id=t.employee_id WHERE t.company_id=? AND t.work_date BETWEEN ? AND ? ORDER BY t.work_date DESC,t.id DESC LIMIT 10001",company,ym.atDay(1),ym.atEndOfMonth());}
    public List<Map<String,Object>> payrollBasis(long company,String month,List<Long> selected){scope(company);var rows=times(company,month(month));if(rows.size()>10000)throw new BadRequestException("Export exceeds 10,000 time entries");return rows.stream().filter(r->"APPROVED".equals(r.get("status")) && (selected==null || selected.isEmpty() || selected.contains(((Number)r.get("id")).longValue()))).toList();}
    private List<Map<String,Object>> invoices(long company){return jdbc.queryForList("SELECT i.*,c.name client,coalesce((SELECT sum(r.amount) FROM public.staffing_receipts r WHERE r.invoice_id=i.id),0) paid,j.reversed_by journal_reversed_by FROM public.staffing_invoices i JOIN public.staffing_clients c ON c.id=i.client_id LEFT JOIN public.accounting_entries j ON j.id=i.journal_id WHERE i.company_id=? ORDER BY i.id DESC LIMIT 5000",company);}
    public Map<String,Object> invoiceDetail(long company,long id){scope(company);var invoice=one("staffing_invoices",company,id);invoice.remove("request_hash");invoice.put("lines",jdbc.queryForList("SELECT * FROM public.staffing_invoice_lines WHERE invoice_id=? ORDER BY id",id));invoice.put("receipts",jdbc.queryForList("SELECT r.id,r.payment_date,r.amount,r.account,r.reference,r.created_by,j.reversed_by journal_reversed_by FROM public.staffing_receipts r JOIN public.accounting_entries j ON j.id=r.journal_id WHERE r.invoice_id=? ORDER BY r.id",id));return invoice;}
    private static BigDecimal lineAmount(Map<String,Object> row,String rate,String otRate){return new BigDecimal(row.get("regular_hours").toString()).multiply(new BigDecimal(row.get(rate).toString())).add(new BigDecimal(row.get("overtime_hours").toString()).multiply(new BigDecimal(row.get(otRate).toString()))).setScale(2,RoundingMode.HALF_UP);}
    public long invoice(long company,Invoice r){
        var c=scope(company);lock(company);text(r.requestKey(),60,"Request key");actual(r.invoiceDate());period(r.invoiceDate(),r.dueDate());if(r.dueDate()==null)throw new BadRequestException("Due date is required");amount(r.taxPercent(),3,"tax percentage");if(r.taxPercent().compareTo(new BigDecimal("100"))>0)throw new BadRequestException("Tax percentage cannot exceed 100");if(r.timeEntryIds()==null || r.timeEntryIds().isEmpty() || r.timeEntryIds().size()>1000 || r.timeEntryIds().stream().anyMatch(Objects::isNull))throw new BadRequestException("Select 1–1,000 approved time entries");
        var ids=new TreeSet<>(r.timeEntryIds());String fingerprint=hash(Arrays.asList(r.clientId(),ids,r.invoiceDate().toString(),r.dueDate().toString(),r.taxPercent().stripTrailingZeros().toPlainString()));var prior=jdbc.queryForList("SELECT id,request_hash FROM public.staffing_invoices WHERE company_id=? AND request_key=?",company,r.requestKey());if(!prior.isEmpty()){if(!fingerprint.equals(prior.getFirst().get("request_hash")))throw new BadRequestException("Request key was used for a different invoice");return ((Number)prior.getFirst().get("id")).longValue();}
        var client=one("staffing_clients",company,r.clientId());if(!Boolean.TRUE.equals(client.get("active")))throw new BadRequestException("Client is inactive");var rows=new ArrayList<Map<String,Object>>();String currency=null;BigDecimal subtotal=money(0);
        for(long id:ids){var row=one("staffing_time_entries",company,id);var assignment=one("staffing_assignments",company,((Number)row.get("assignment_id")).longValue());if(!"APPROVED".equals(row.get("status")) || linked(id) || ((Number)assignment.get("client_id")).longValue()!=r.clientId())throw new BadRequestException("Select unbilled approved hours for one client");if(day(row.get("work_date")).isAfter(r.invoiceDate()))throw new BadRequestException("Invoice date cannot precede worked hours");checkSource(c,row);if(currency==null)currency=(String)row.get("currency");if(!Objects.equals(currency,row.get("currency")))throw new BadRequestException("Invoice must have one currency");row.put("title",assignment.get("title"));subtotal=subtotal.add(lineAmount(row,"bill_rate","overtime_bill_rate"));rows.add(row);}
        if(subtotal.signum()==0)throw new BadRequestException("Invoice total must be positive");BigDecimal tax=subtotal.multiply(r.taxPercent()).divide(new BigDecimal("100"),2,RoundingMode.HALF_UP);if(subtotal.add(tax).precision()>16)throw new BadRequestException("Invoice amount is too large");
        long id=jdbc.queryForObject("INSERT INTO public.staffing_invoices(company_id,client_id,invoice_date,due_date,currency,subtotal,tax_percent,tax_amount,total,client_snapshot,request_key,request_hash,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,company,r.clientId(),r.invoiceDate(),r.dueDate(),currency,subtotal,r.taxPercent(),tax,subtotal.add(tax),encode(client),r.requestKey(),fingerprint,actor());
        for(var row:rows)jdbc.update("INSERT INTO public.staffing_invoice_lines(invoice_id,time_entry_id,description,regular_hours,overtime_hours,bill_rate,overtime_bill_rate,amount) VALUES(?,?,?,?,?,?,?,?)",id,row.get("id"),row.get("title")+" · "+row.get("work_date"),row.get("regular_hours"),row.get("overtime_hours"),row.get("bill_rate"),row.get("overtime_bill_rate"),lineAmount(row,"bill_rate","overtime_bill_rate"));audit("invoice",id,null,r);return id;
    }
    private void currency(long company,Map<String,Object> invoice){String current=jdbc.queryForObject("SELECT currency FROM public.companies WHERE id=?",String.class,company);if(!Objects.equals(current,invoice.get("currency")))throw new BadRequestException("Company currency differs from invoice currency; review accounting before posting");}
    private long journal(long company,String request,LocalDate date,String description,String reference,List<AccountingService.Line> lines){return accounting.journal(company,new AccountingService.JournalRequest(request,date,"JOURNAL",description,reference,lines));}
    public void issue(long company,long id){var c=scope(company);lock(company);var row=one("staffing_invoices",company,id);if("ISSUED".equals(row.get("status")))return;if(!"DRAFT".equals(row.get("status")))throw new BadRequestException("Only a draft invoice can be issued");currency(company,row);for(long time:jdbc.queryForList("SELECT time_entry_id FROM public.staffing_invoice_lines WHERE invoice_id=?",Long.class,id))checkSource(c,one("staffing_time_entries",company,time));
        var lines=new ArrayList<AccountingService.Line>();lines.add(new AccountingService.Line("RECEIVABLES",money(row.get("total")),money(0)));lines.add(new AccountingService.Line("INCOME",money(0),money(row.get("subtotal"))));if(money(row.get("tax_amount")).signum()>0){var taxAccounts=accounting.accounts(company);if(taxAccounts.stream().anyMatch(a->"SALES_TAX_PAYABLE".equals(a.get("code")) && !"LIABILITY".equals(a.get("type"))))throw new BadRequestException("Sales tax account must be a liability");if(taxAccounts.stream().noneMatch(a->"SALES_TAX_PAYABLE".equals(a.get("code"))))accounting.createAccount(company,"SALES_TAX_PAYABLE","Sales tax payable (review jurisdiction)","LIABILITY");lines.add(new AccountingService.Line("SALES_TAX_PAYABLE",money(0),money(row.get("tax_amount"))));}
        long journal=journal(company,"STAFF-INV:"+id,day(row.get("invoice_date")),"Client invoice #"+id,"STAFF-"+id,lines);jdbc.update("UPDATE public.staffing_invoices SET status='ISSUED',journal_id=? WHERE id=?",journal,id);audit("invoice issue",id,row,Map.of("journal",journal));}
    public long receipt(long company,long id,Receipt r){scope(company);lock(company);var invoice=one("staffing_invoices",company,id);actual(r.date());amount(r.amount(),2,"receipt amount");if(r.amount().signum()==0)throw new BadRequestException("Receipt must be positive");choice(r.account(),Set.of("BANK","CASH"),"payment account");text(r.reference(),160,"Payment reference");text(r.requestKey(),60,"Request key");String fingerprint=hash(Arrays.asList(id,r.date().toString(),r.amount().stripTrailingZeros().toPlainString(),r.account(),r.reference()));var prior=jdbc.queryForList("SELECT id,request_hash FROM public.staffing_receipts WHERE company_id=? AND request_key=?",company,r.requestKey());if(!prior.isEmpty()){if(!fingerprint.equals(prior.getFirst().get("request_hash")))throw new BadRequestException("Request key was used for a different receipt");return ((Number)prior.getFirst().get("id")).longValue();}if(!"ISSUED".equals(invoice.get("status")))throw new BadRequestException("Issue the invoice before recording payment");if(r.date().isBefore(day(invoice.get("invoice_date"))))throw new BadRequestException("Receipt date cannot precede invoice date");currency(company,invoice);if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT reversed_by IS NOT NULL FROM public.accounting_entries WHERE id=?",Boolean.class,invoice.get("journal_id"))))throw new BadRequestException("Invoice journal was reversed; reconcile before recording receipts");BigDecimal paid=jdbc.queryForObject("SELECT coalesce(sum(amount),0) FROM public.staffing_receipts WHERE invoice_id=?",BigDecimal.class,id);if(paid.add(r.amount()).compareTo(money(invoice.get("total")))>0)throw new BadRequestException("Receipt exceeds outstanding invoice balance");long journal=journal(company,"STAFF-RCPT:"+r.requestKey(),r.date(),"Client receipt for invoice #"+id,r.reference(),List.of(new AccountingService.Line(r.account(),r.amount(),money(0)),new AccountingService.Line("RECEIVABLES",money(0),r.amount())));long receipt=jdbc.queryForObject("INSERT INTO public.staffing_receipts(invoice_id,company_id,payment_date,amount,account,reference,request_key,request_hash,journal_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,id,company,r.date(),r.amount(),r.account(),r.reference(),r.requestKey(),fingerprint,journal,actor());audit("receipt",receipt,null,Map.of("invoice",id,"amount",r.amount(),"reference",r.reference()));return receipt;}
    public void voidInvoice(long company,long id,VoidInvoice r){scope(company);lock(company);var invoice=one("staffing_invoices",company,id);if("VOID".equals(invoice.get("status")))return;text(r.reason(),400,"Void reason");actual(r.date());if(r.date().isBefore(day(invoice.get("invoice_date"))))throw new BadRequestException("Void date cannot precede invoice date");if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM public.staffing_receipts WHERE invoice_id=?)",Boolean.class,id)))throw new BadRequestException("An invoice with recorded receipts cannot be voided; reconcile with finance");if(invoice.get("journal_id")!=null)accounting.reverse(company,((Number)invoice.get("journal_id")).longValue(),new AccountingService.ReverseRequest(r.reason(),r.date(),r.requestKey()));jdbc.update("UPDATE public.staffing_invoices SET status='VOID',void_reason=?,voided_by=? WHERE id=?",r.reason(),actor(),id);jdbc.update("UPDATE public.staffing_invoice_lines SET released=true WHERE invoice_id=?",id);audit("invoice void",id,invoice,r);}
}
